SELECT p.gender, CAST(p.anchor_age AS INT) AS age, s.stay_length, d.diagnosis_type, COUNT(DISTINCT u.procedure_id) AS num_ultrasounds FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN procedures_icd u ON a.subject_id = u.subject_id AND u.chartdate BETWEEN p.dod AND (p.dod + interval '7 days') WHERE p.gender = 'M' AND CAST(p.anchor_age AS INT) BETWEEN 83 AND 93 AND s.stay_length BETWEEN 1 AND 7 AND d.icd_code = 'ACS' GROUP BY p.gender, age, stay_length, diagnosis_type ORDER BY p.gender, age, stay_length, diagnosis_type NULLS LAST;